namespace sv_caf7685a8093446cb68c47e8613403ab.Services;

public class WarehouseInfo
{
    public string Id { get; set; } = default!;
    public string Name { get; set; } = default!;
}

/// <summary>
/// Scoped service that holds the currently selected warehouse for a single user circuit.
/// Components subscribe to OnChange to react when the selection changes.
/// </summary>
public class WarehouseState
{
    private static readonly List<WarehouseInfo> _availableWarehouses =
    [
        new() { Id = "wh-1", Name = "Warehouse A" },
        new() { Id = "wh-2", Name = "Warehouse B" },
        new() { Id = "wh-3", Name = "Warehouse C" },
    ];

    public IReadOnlyList<WarehouseInfo> AvailableWarehouses => _availableWarehouses;

    public string CurrentWarehouseId { get; private set; } = "wh-1";

    public string CurrentWarehouseName =>
        _availableWarehouses.First(w => w.Id == CurrentWarehouseId).Name;

    public event Action? OnChange;

    public void SetWarehouse(string warehouseId)
    {
        if (CurrentWarehouseId == warehouseId) return;
        CurrentWarehouseId = warehouseId;
        OnChange?.Invoke();
    }
}

namespace sv_caf7685a8093446cb68c47e8613403ab.Services;

