@using sv_caf7685a8093446cb68c47e8613403ab.Services
@inject WarehouseState WarehouseState
@implements IDisposable
@rendermode InteractiveServer

<select class="form-select form-select-sm" style="width: auto;"
        value="@WarehouseState.CurrentWarehouseId"
        @onchange="OnWarehouseChanged">
    @foreach (var wh in WarehouseState.AvailableWarehouses)
    {
        <option value="@wh.Id">@wh.Name</option>
    }
</select>

@code {
    protected override void OnInitialized()
    {
        WarehouseState.OnChange += HandleStateChange;
    }

    private void OnWarehouseChanged(ChangeEventArgs e)
    {
        var newId = e.Value?.ToString();
        if (!string.IsNullOrEmpty(newId))
        {
            WarehouseState.SetWarehouse(newId);
        }
    }

    private void HandleStateChange() => InvokeAsync(StateHasChanged);

    public void Dispose()
    {
        WarehouseState.OnChange -= HandleStateChange;
    }
}

@using sv_caf7685a8093446cb68c47e8613403ab.Services
@inject InventoryAlertState AlertState
@implements IDisposable
@rendermode InteractiveServer

<span class="badge bg-danger rounded-pill">@AlertState.LowStockCount</span>

@code {
    protected override void OnInitialized()
    {
        AlertState.OnChange += HandleAlertChange;
    }

    private void HandleAlertChange() => InvokeAsync(StateHasChanged);

    public void Dispose()
    {
        AlertState.OnChange -= HandleAlertChange;
    }
}

@page "/dashboard"
@using sv_caf7685a8093446cb68c47e8613403ab.Services
@inject WarehouseState WarehouseState
@inject InventoryAlertService AlertService
@inject InventoryAlertState AlertState
@implements IDisposable
@rendermode InteractiveServer

<PageTitle>Dashboard</PageTitle>

<h1>Warehouse Dashboard</h1>
<p class="text-muted">Currently viewing: <strong>@WarehouseState.CurrentWarehouseName</strong></p>

<div class="card mt-3" style="max-width: 400px;">
    <div class="card-body">
        <h5 class="card-title">Low Stock Alerts</h5>
        <p class="card-text display-4 text-danger">@AlertState.LowStockCount</p>
        <p class="card-text text-muted">
            Items below minimum stock level. Refreshes every 10 seconds.
        </p>
    </div>
</div>

@code {
    private PeriodicTimer? _timer;
    private CancellationTokenSource? _cts;

    protected override void OnInitialized()
    {
        WarehouseState.OnChange += OnWarehouseChanged;
    }

    protected override async Task OnInitializedAsync()
    {
        // Initial fetch
        await RefreshAlertCount();
        // Start polling
        StartPolling();
    }

    private void StartPolling()
    {
        _cts = new CancellationTokenSource();
        _timer = new PeriodicTimer(TimeSpan.FromSeconds(10));
        _ = PollLoop(_cts.Token);
    }

    private async Task PollLoop(CancellationToken cancellationToken)
    {
        try
        {
            while (await _timer!.WaitForNextTickAsync(cancellationToken))
            {
                await RefreshAlertCount();
            }
        }
        catch (OperationCanceledException)
        {
            // Expected on dispose
        }
    }

    private async Task RefreshAlertCount()
    {
        var count = await AlertService.GetLowStockCountAsync(WarehouseState.CurrentWarehouseId);
        // Update shared state — this notifies ALL subscribers (sidebar badge, this page, etc.)
        AlertState.UpdateCount(count);
    }

    private void OnWarehouseChanged()
    {
        // Warehouse changed: immediately refresh alert count for new warehouse
        InvokeAsync(async () =>
        {
            await RefreshAlertCount();
            StateHasChanged();
        });
    }

    public void Dispose()
    {
        WarehouseState.OnChange -= OnWarehouseChanged;
        _cts?.Cancel();
        _cts?.Dispose();
        _timer?.Dispose();
    }
}

